function lerCsv() {
    const CAMINHO_CSV = 'C:\\woodscan\\contagem.csv';
    if (!fs.existsSync(CAMINHO_CSV)) return [];
    const linhas = fs.readFileSync(CAMINHO_CSV, 'utf8').trim().split('\n');
    linhas.shift(); // remove cabecalho
    return linhas.filter(Boolean).map(function (linha) {
        var partes = linha.split(',');
        return {
            data: partes[0], turno: partes[1], esteira: partes[2],
            timestamp: partes[3], temperatura: partes[4], umidade: partes[5]
        };
    });
}

function turnoAtual() {
    var hora = new Date().getHours();
    if (hora >= 6 && hora < 14) return 'manha';
    if (hora >= 14 && hora < 22) return 'tarde';
    return 'noite';
}

function resumoEsteira(codigo) {
    var registros = lerCsv().filter(function (r) { return r.esteira === codigo; });
    var hoje = new Date().toISOString().slice(0, 10);
    var turno = turnoAtual();
    var doTurno = registros.filter(function (r) { return r.data === hoje && r.turno === turno; });
    var ultimo = registros[registros.length - 1];

    return {
        contagem_atual: doTurno.length,
        turno_atual: doTurno.length > 0 ? turno : null,
        temperatura: ultimo ? parseFloat(ultimo.temperatura) || null : null,
        umidade: ultimo ? parseFloat(ultimo.umidade) || null : null
    };
}

